parameters.jsCode:
// The dead-man's switch. ADR 0002: if no published row exists for the current
// week by 14:00 PT Tuesday, alert. Silence itself has to be the alarm, so this
// alarms on an UNREACHABLE index exactly as loudly as on a stale one.
//
// THE SIGNAL is index.json's seasons[].weeks[].published_at, which
// `cfbpoll publish fixtures` stamps on every export. We do not need to know
// which week it is; we need to know that the current season's newest week was
// published today. That is checkable with no API key and no database.
//
// READ THIS BEFORE CHANGING THE LOGIC: `played: true` in that document does NOT
// mean "the games were played". `publish/fixtures.rebuild_index` sets it only
// for weeks that HAVE a published document, and fills every other week of the
// schedule from `serving.unplayed_week`, which writes `published_at: null`. So
// `played` cannot be used to detect "the games happened and we published
// nothing" - that is exactly the outage this switch is for, and the flag would
// read false during it. The timestamp is the only honest signal here.

// The first Tuesday this season is expected to publish, which is the Tuesday
// AFTER the Labor Day opener: week 1 does not finish until the Monday night
// game. Before this date, a season with no published weeks is a season that has
// not started, not an outage.
// UPDATE THIS ONE LINE EACH AUGUST.
const FIRST_PUBLISH_DATE = '2026-09-08';

// 14:00 PT back past midnight: a publication from this morning is fresh, one
// from last Tuesday is not.
const STALE_AFTER_HOURS = 14;

const input = $input.first().json || {};
const status = input.statusCode;
const body = input.body;

function alarm(headline, detail) {
  return [{ json: { alarm: true, headline, detail, checked_at: new Date().toISOString() } }];
}

if (typeof status === 'number' && status >= 400) {
  return alarm(
    'The poll index is not being served (HTTP ' + status + ')',
    'The dead-man\'s switch could not read index.json. Either the site is down or the URL in this n8n workflow is wrong. Both need a human.'
  );
}

if (!body || !Array.isArray(body.seasons)) {
  return alarm(
    'The poll index is unreadable',
    'index.json was fetched but carries no seasons array. Expected the document that cfbpoll publish fixtures writes.'
  );
}

// The same Feb-to-Jan convention as cfbpoll.ops.guard.current_season: a January
// playoff game is the tail of the season that started the previous August.
const nowLA = new Date(new Date().toLocaleString('en-US', { timeZone: 'America/Los_Angeles' }));
const season = nowLA.getMonth() + 1 >= 2 ? nowLA.getFullYear() : nowLA.getFullYear() - 1;

// -07:00 is Pacific DAYLIGHT time, which is what early September is. The offset
// is spelled rather than left to the container's local clock, which is not
// necessarily the workflow's timezone.
if (Date.now() < Date.parse(FIRST_PUBLISH_DATE + 'T00:00:00-07:00')) {
  return [];
}

const block = body.seasons.find(function (s) { return Number(s.season) === season; });
if (!block || !Array.isArray(block.weeks)) {
  return alarm(
    'The poll index has no ' + season + ' season at all',
    'index.json carries seasons ' + body.seasons.map(function (s) { return s.season; }).join(', ') +
      '. The weekly job has never written a ' + season + ' week.'
  );
}

const published = block.weeks
  .map(function (w) { return { week: w.week, at: Date.parse(w.published_at || '') }; })
  .filter(function (w) { return Number.isFinite(w.at); })
  .sort(function (a, b) { return b.at - a.at; });

if (published.length === 0) {
  return alarm(
    'The ' + season + ' season has never published a week',
    'Every week in the ' + season + ' block has published_at: null, which is what the index looks like before the first weekly job ever succeeds. Check the weekly workflow at https://github.com/vyhlidal/cfb-poll/actions/workflows/weekly.yml'
  );
}

const newest = published[0];
const ageHours = (Date.now() - newest.at) / 3600000;

if (ageHours > STALE_AFTER_HOURS) {
  return alarm(
    'The ' + season + ' poll did not publish this morning',
    'The newest published week is ' + season + ' week ' + newest.week + ', published ' +
      new Date(newest.at).toISOString() + ', which is ' + ageHours.toFixed(1) +
      ' hours ago. All three clocks have had their turn: n8n at 06:00 PT, the GitHub schedule, and the VPS timer at 08:30 PT. Check https://github.com/vyhlidal/cfb-poll/actions/workflows/weekly.yml and run: systemctl status cfb-poll-weekly.service'
  );
}

// Nothing to say. Zero items means the email node never fires, and a quiet
// inbox is the signal that the poll went out.
return [];

parameters.text:
={{ $json.headline }}

{{ $json.detail }}

Checked at {{ $json.checked_at }} by the n8n dead-man's switch on the Hostinger VPS.
This message is sent ONLY when the poll did not publish. Silence from this address means the poll went out.
